import unittest

from src.price import apply_discount


class PublicTests(unittest.TestCase):
    def test_whole_percentage(self):
        self.assertEqual(apply_discount(100, 20), 80)

    def test_zero_discount(self):
        self.assertEqual(apply_discount(50, 0), 50)

import unittest

from src.ranges import take


class PublicTests(unittest.TestCase):
    def test_inclusive_end(self):
        self.assertEqual(take([10, 20, 30], 0, 1), [10, 20])

    def test_middle(self):
        self.assertEqual(take([1, 2, 3, 4], 1, 2), [2, 3])

